import { readFileSync } from "fs";
import { join } from "path";
import type { Metadata } from "next";
import { RecipeList } from "./RecipeList";

export const metadata: Metadata = {
  title: "Oppskrifts-AEO | APRIIL",
  description:
    "Strukturerte AEO-innholdsblokker generert fra melk.no sitt oppskriftsbibliotek.",
  robots: {
    index: false,
    follow: false,
    nocache: true,
    googleBot: { index: false, follow: false },
  },
};

export type FAQItem = {
  question: string;
  answer: string;
  type: string;
  score: number;
};

export type RecipeSignals = {
  has_milk: boolean;
  has_egg: boolean;
  is_fried: boolean;
  is_baked: boolean;
  is_sweet: boolean;
};

export type RecipeMetadata = {
  ingredients: string[];
  category: string | null;
  cooking_method: string;
  allergens: string[];
  signals: RecipeSignals;
};

export type RecipeAEOBlock = {
  recipe: string;
  primary_answer: string;
  faqs: FAQItem[];
  micro_answers: string[];
  metadata: RecipeMetadata;
};

function loadRecipes(): RecipeAEOBlock[] {
  try {
    const raw = readFileSync(
      join(process.cwd(), "public/data/aeo_output.json"),
      "utf-8"
    );
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

export default function OppskrifterPage() {
  const recipes = loadRecipes();

  const totalFaqs = recipes.reduce((sum, r) => sum + r.faqs.length, 0);

  return (
    <main className="min-h-screen bg-black pb-32">
      <div className="mx-auto w-full max-w-[1600px] px-6 py-24 md:px-12 xl:px-40">
        {/* Header */}
        <div className="border-b border-[#EAEAEA]/10 pb-12">
          <p className="text-xs uppercase tracking-[0.2em] text-[#EAEAEA]/50">
            AEO pipeline · melk.no
          </p>
          <h1 className="mt-4 text-4xl leading-tight tracking-tight text-[#EAEAEA] md:text-6xl">
            Oppskrifts-AEO
          </h1>
          <p className="mt-5 max-w-3xl text-base leading-relaxed text-[#B0B0B0] md:text-lg">
            {recipes.length > 0 ? (
              <>
                {recipes.length} oppskrifter er konvertert til strukturerte
                AEO-innholdsblokker med{" "}
                <span className="text-[#EAEAEA]">{totalFaqs} FAQ-spørsmål</span>
                , primærsvar og mikrosvar klare for implementering.
              </>
            ) : (
              "Pipeline-output lastes inn. Kjør aeo:sync for å kopiere outputfiler hit."
            )}
          </p>

          {/* Download links */}
          {recipes.length > 0 && (
            <div className="mt-6 flex flex-wrap gap-6">
              <a
                href="/data/aeo_output.json"
                download
                className="inline-flex items-center gap-2 text-sm text-[#EAEAEA]/60 underline underline-offset-4 transition-colors hover:text-[#EAEAEA]"
              >
                ↓ Last ned JSON
              </a>
              <a
                href="/data/aeo_output.csv"
                download
                className="inline-flex items-center gap-2 text-sm text-[#EAEAEA]/60 underline underline-offset-4 transition-colors hover:text-[#EAEAEA]"
              >
                ↓ Last ned CSV
              </a>
              <a
                href="/data/aeo_output.html"
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-2 text-sm text-[#EAEAEA]/60 underline underline-offset-4 transition-colors hover:text-[#EAEAEA]"
              >
                ↗ Vis HTML-rapport
              </a>
            </div>
          )}
        </div>

        {/* Recipe list */}
        {recipes.length > 0 ? (
          <RecipeList recipes={recipes} />
        ) : (
          <div className="mt-20 text-center">
            <p className="text-[#B0B0B0]">
              Ingen oppskrifter funnet. Sørg for at{" "}
              <code className="rounded bg-[#EAEAEA]/10 px-1 py-0.5 text-sm text-[#EAEAEA]/80">
                public/data/aeo_output.json
              </code>{" "}
              eksisterer.
            </p>
            <p className="mt-3 text-sm text-[#EAEAEA]/40">
              Kjør:{" "}
              <code className="rounded bg-[#EAEAEA]/10 px-1 py-0.5 text-[#EAEAEA]/70">
                npm run aeo:sync
              </code>
            </p>
          </div>
        )}
      </div>
    </main>
  );
}
